describe('Logout Functionality - Sauce Labs', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should log out successfully and return to login page', () => {
    // Verify login page is visible
    cy.get('[data-test="login-button"]').should('be.visible');
    cy.get('[data-test="username"]').should('be.visible');
    cy.get('[data-test="password"]').should('be.visible');

    // Fill in login credentials
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');

    // Click login button
    cy.get('[data-test="login-button"]').click();

    // Verify login was successful and user is redirected to dashboard
    cy.url().should('include', '/dashboard');
    cy.get('[data-test="active-option"]').should('contain', 'dashboard');

    // Verify logout link is visible
    cy.get('#logout_sidebar_link').should('be.visible');

    // Click logout link
    cy.get('#logout_sidebar_link').click();

    // Verify user is redirected back to login page
    cy.url().should('include', '/login');
    cy.get('[data-test="login-button"]').should('be.visible');

    // Verify login button is visible again
    cy.get('[data-test="login-button"]').should('be.visible');
  });

  it('should handle logout when user is already logged out', () => {
    // Verify login page is visible
    cy.get('[data-test="login-button"]').should('be.visible');

    // Click logout link
    cy.get('#logout_sidebar_link').click();

    // Verify user is redirected to login page
    cy.url().should('include', '/login');
    cy.get('[data-test="login-button"]').should('be.visible');

    // Verify logout link is still visible
    cy.get('#logout_sidebar_link').should('be.visible');

    // Verify logout button is still visible
    cy.get('#logout_sidebar_link').should('be.visible');
  });
});
